async function previewCableScrapImport(rows) {
  const prisma2 = requirePrisma7();
  const previewRows = [];
  let validCount = 0;
  let errorCount = 0;
  for (let idx = 0; idx < rows.length; idx++) {
    const row2 = rows[idx];
    const rowNumber = idx + 2;
    const errors = [];
    const warnings = [];
    const materialNumber = asTrimmedString(
      getExcelVal(row2, ["Cable Material Number", "Material Number", "CableMaterialNumber"])
    );
    const metal = normalizeFilterToken(
      asTrimmedString(getExcelVal(row2, ["Metal", "Conductor Metal"]))
    );
    const family = asTrimmedString(getExcelVal(row2, ["Family", "Cable Family"]));
    const scrapRaw = getExcelVal(row2, ["Scrap %", "Scrape %", "Scrap", "Scrape", "Scrap Percent"]);
    if (!materialNumber) {
      errors.push({ field: "Cable Material Number", message: "Cable Material Number is required.", code: "REQUIRED" });
    }
    const scrapParsed = parseScrapPercentInput(scrapRaw);
    if (scrapParsed.ok === false) {
      if (scrapRaw == null || scrapRaw === "") {
        warnings.push({ field: "Scrap %", message: "Scrap % is blank \u2014 row will be skipped on commit.", code: "SKIPPED" });
      } else {
        errors.push({ field: "Scrap %", message: scrapParsed.message, code: "INVALID_SCRAP_RATE" });
      }
    }
    let bomLineCount = 0;
    if (materialNumber) {
      const cable = await prisma2.cableMaster.findUnique({
        where: { materialNumber },
        include: { engineeringMappings: { where: { isCurrent: true }, take: 1 } }
      });
      if (!cable) {
        errors.push({
          field: "Cable Material Number",
          message: `Cable "${materialNumber}" was not found in Cable Master.`,
          code: "CABLE_NOT_FOUND"
        });
      } else {
        const mapping = cable.engineeringMappings[0];
        const cableFamily = mapping?.family || cable.family || "";
        const cableMetal = deriveMetalFromConductor(mapping?.conductor || cable.conductor);
        if (metal && cableMetal && metal !== cableMetal) {
          errors.push({
            field: "Metal",
            message: `Metal ${metal} does not match cable master (${cableMetal}).`,
            code: "METAL_MISMATCH"
          });
        }
        if (family && cableFamily && normalizeFilterToken(family) !== normalizeFilterToken(cableFamily)) {
          errors.push({
            field: "Family",
            message: `Family ${family} does not match cable master (${cableFamily}).`,
            code: "FAMILY_MISMATCH"
          });
        }
        const bom = await getBomScrapLines(materialNumber);
        bomLineCount = bom.lines.length;
        if (bomLineCount === 0) {
          errors.push({
            field: "Cable Material Number",
            message: `Cable "${materialNumber}" has no BOM lines to apply scrap.`,
            code: "BOM_NOT_FOUND"
          });
        }
      }
    }
    const status = errors.length > 0 ? "ERROR" : warnings.length > 0 ? "WARNING" : "VALID";
    if (status === "VALID") validCount += 1;
    if (status === "ERROR") errorCount += 1;
    previewRows.push({
      rowNumber,
      cableMaterialNumber: materialNumber,
      scrapPercent: scrapParsed.ok ? scrapParsed.percent : null,
      metal,
      family,
      status,
      bomLineCount,
      errors,
      warnings
    });
  }
  return { rows: previewRows, validCount, errorCount };
}
async function commitCableScrapImport(rows, actor) {
  const preview = await previewCableScrapImport(rows);
  const errors = [];
  let updatedCables = 0;
  let skippedRows = 0;
  for (const row2 of preview.rows) {
    if (row2.status === "ERROR") {
      errors.push({
        rowNumber: row2.rowNumber,
        message: row2.errors.map((e) => e.message).join(" "),
        code: row2.errors[0]?.code || "IMPORT_ERROR"
      });
      continue;
    }
    if (row2.scrapPercent == null) {
      skippedRows += 1;
      continue;
    }
    const bom = await getBomScrapLines(row2.cableMaterialNumber);
    if (bom.lines.length === 0) {
      errors.push({
        rowNumber: row2.rowNumber,
        message: `No BOM lines for cable ${row2.cableMaterialNumber}.`,
        code: "BOM_NOT_FOUND"
      });
      continue;
    }
    await bulkUpdateBomScrap(
      row2.cableMaterialNumber,
      bom.lines.map((line) => ({
        id: line.id,
        source: line.source,
        scrapPercent: row2.scrapPercent
      })),
      actor
    );
    updatedCables += 1;
  }
  return { updatedCables, skippedRows, errors };
}

