function isSyntheticRawMaterialCode(code) {
  const normalized = code.trim().toUpperCase();
  return /^I\d+-RM-/.test(normalized) || /^I\d+D-RM-/.test(normalized) || /^I\d+_TEST/.test(normalized) || /^I\d+-TEST/.test(normalized) || normalized.startsWith("TEST-") || normalized.startsWith("TEST_");
}

