costingAdminRouter.post("/bulk-import/preview", async (req, res) => {
  const actor = await actorFromRequest3(req);
  try {
    assertCanManageCostingConfiguration(actor);
  } catch (err) {
    return handleAuthError(err, res);
  }
  const { kind, rows, sourceFile } = req.body || {};
  if (!kind || !Array.isArray(rows)) {
    return res.status(400).json({ error: "kind and rows are required.", code: "VALIDATION_ERROR" });
  }
  try {
    const pipelineKind = costingBulkPipelineKind(kind);
    if (pipelineKind) {
      const preview2 = await runCostingPipelineImport(
        pipelineKind,
        rows,
        String(sourceFile || "upload.xlsx"),
        actor,
        false
      );
      return res.json({ ...preview2, rows });
    }
    const preview = previewCostingBulkImport(
      kind,
      rows,
      String(sourceFile || "upload.xlsx"),
      actor.name || actor.email || actor.id || "system"
    );
    if (String(kind) === "metal_cost_components") {
      return res.json(previewMetalCostComponentBulk(rows, String(sourceFile || "upload.xlsx")));
    }
    if (["raw_material_prices", "currencies", "exchange_rates", "scrap_rules"].includes(String(kind))) {
      const governed = await previewGovernedCostingBulk(String(kind), rows, String(sourceFile || "upload.xlsx"));
      return res.json(governed);
    }
    res.json({ ...preview, rows });
  } catch (err) {
    handleFormulaError(err, res);
  }
});
costingAdminRouter.post("/bulk-import/commit", async (req, res) => {
  const actor = await actorFromRequest3(req);
  try {
    assertCanManageCostingConfiguration(actor);
  } catch (err) {
    return handleAuthError(err, res);
  }
  const { kind, rows, sourceFile } = req.body || {};
  if (!kind || !Array.isArray(rows)) {
    return res.status(400).json({ error: "kind and rows are required.", code: "VALIDATION_ERROR" });
  }
  try {
    const pipelineKind = costingBulkPipelineKind(kind);
    if (pipelineKind) {
      const result2 = await runCostingPipelineImport(
        pipelineKind,
        rows,
        String(sourceFile || "upload.xlsx"),
        actor,
        true
      );
      if (result2.batch.errorCount > 0) {
        await persistImportBatchOnly(result2.batch, "REJECTED").catch(() => void 0);
        return res.status(422).json({
          result: result2,
          committed: false,
          message: "Import rejected. No ERROR rows were written."
        });
      }
      await persistImportTransaction({
        kind: pipelineKind,
        batch: {
          ...result2.batch,
          status: "COMMITTED",
          successCount: result2.cables?.length || result2.boms?.length || result2.drums?.length || result2.rawMaterials?.length || 0
        },
        cables: result2.cables,
        boms: result2.boms,
        drums: result2.drums,
        rawMaterials: result2.rawMaterials,
        duplicateObservations: result2.duplicateObservations,
        actor
      });
      return res.json({ result: { ...result2, batch: { ...result2.batch, status: "COMMITTED" } }, message: "Bulk import committed." });
    }
    if (String(kind) === "metal_cost_components") {
      const result2 = await commitMetalCostComponentBulk(
        rows,
        String(sourceFile || "upload.xlsx"),
        actor
      );
      return res.json({ result: result2, message: "Bulk import committed as Draft. Records were not auto-approved." });
    }
    const result = commitCostingBulkImport(
      kind,
      rows,
      String(sourceFile || "upload.xlsx"),
      actor.name || actor.email || actor.id || "system"
    );
    res.json({ result, message: "Bulk import committed." });
  } catch (err) {
    handleFormulaError(err, res);
  }
});
