init_db();
async function getPlatformKpis() {
  const prisma2 = getPrisma();
  if (!prisma2) {
    return {
      activeCustomers: 0,
      openInquiries: 0,
      openQuotations: 0,
      costingReadyCables: 0,
      bomConflicts: 0,
      unpricedRawMaterials: 0,
      technicalOfficeRequests: 0,
      pendingApprovals: 0,
      inquiryByStatus: [],
      quotationByStatus: []
    };
  }
  const [
    activeCustomers,
    openInquiries,
    openQuotations,
    bomConflicts,
    unpricedRawMaterials,
    technicalOfficeRequests,
    pendingScrap,
    pendingFx,
    inquiryGroups,
    quotationGroups,
    costingReady
  ] = await Promise.all([
    prisma2.customer.count({ where: { status: "ACTIVE" } }),
    prisma2.commercialInquiry.count({
      where: { isCurrent: true, status: { in: ["DRAFT", "UNDER_REVIEW", "SUBMITTED"] } }
    }),
    prisma2.commercialQuotation.count({
      where: { isCurrent: true, status: { in: ["DRAFT", "OPEN", "SUBMITTED"] } }
    }),
    prisma2.bomDuplicateObservation.count({
      where: { investigationStatus: { not: "RESOLVED" } }
    }),
    prisma2.rawMaterial.count({ where: { priceStatus: "PRICE_NOT_CONFIGURED" } }),
    prisma2.technicalOfficeRequest.count({
      where: { canonicalStatus: { in: ["PENDING", "IN_REVIEW", "SUBMITTED"] } }
    }),
    prisma2.costingScrapRule.count({ where: { workflowStatus: "SUBMITTED" } }),
    prisma2.costingExchangeRate.count({ where: { workflowStatus: "SUBMITTED" } }),
    prisma2.commercialInquiry.groupBy({ by: ["status"], where: { isCurrent: true }, _count: true }),
    prisma2.commercialQuotation.groupBy({ by: ["status"], where: { isCurrent: true }, _count: true }),
    prisma2.costingCalculation.count({ where: { status: { in: ["LOCKED", "READY"] } } })
  ]);
  return {
    activeCustomers,
    openInquiries,
    openQuotations,
    costingReadyCables: costingReady,
    bomConflicts,
    unpricedRawMaterials,
    technicalOfficeRequests,
    pendingApprovals: pendingScrap + pendingFx,
    inquiryByStatus: inquiryGroups.map((g) => ({ status: g.status, count: g._count })),
    quotationByStatus: quotationGroups.map((g) => ({ status: g.status, count: g._count }))
  };
}

