    doc.roundedRect(LEFT, y, colW, partyH, 4).fillAndStroke("#F7FAFC", RULE);
    doc.roundedRect(LEFT + colW + 6, y, colW, partyH, 4).fillAndStroke("#F7FAFC", RULE);
